mapper.select:
SELECT * FROM dev_sample_order WHERE tenant_key=#{tenant} AND company_id=#{companyId} AND sample_id=#{sampleId}
AND sample_version < #{beforeVersion}
ORDER BY sample_version DESC LIMIT #{limit}

mapper.update:
UPDATE dev_sample_order SET sample_type=#{row.sampleType},make_way=#{row.makeWay},factory_id=#{row.factoryId},
    maker_id=#{row.makerId},need_date=#{row.needDate},qty=#{row.qty},size_group_id=#{row.sizeGroupId},reason=#{row.reason},
    requirement=#{row.requirement},status=#{row.status},dispatched_by=#{row.dispatchedBy},dispatched_time=#{row.dispatchedTime},
    version=version+1,update_by=#{row.updateBy},update_time=clock_timestamp()
WHERE tenant_key=#{tenant} AND company_id=#{companyId} AND id=#{row.id} AND sample_id=#{row.sampleId}
    AND version=#{expectedVersion} AND version < 2147483647 AND status=#{expectedStatus}
